<?php
require_once __DIR__ . '/../../admin/implements/conexion.php';exigirSesion();if(($_SESSION['usuario']['rol']??'')!=='Usuario'){header('Location: /app_biblioteca/admin/dashboard.php');exit;}$s=$pdo->prepare("SELECT p.*,l.titulo,l.autor,IF(p.estado_prestamo='Activo' AND p.fecha_devolucion<CURDATE(),'Atrasado',p.estado_prestamo) estado_vista FROM prestamos p JOIN libros l ON l.id_libro=p.id_libro WHERE p.id_usuario=? ORDER BY p.id_prestamo DESC");$s->execute([(int)$_SESSION['usuario']['id_usuario']]);$rows=$s->fetchAll();iniciarPagina('Mis préstamos');
?>
<nav class="navbar navbar-dark barra"><div class="container-fluid"><a class="navbar-brand" href="/app_biblioteca/admin/usuarios/mi-cuenta.php">Biblioteca · Mi cuenta</a><span class="navbar-text me-auto"><?= escapar($_SESSION['usuario']['nombre']); ?></span><form method="post" action="/app_biblioteca/admin/login/log-out.php"><input type="hidden" name="token_csrf" value="<?= escapar(tokenCsrf()); ?>"><button class="btn btn-outline-light btn-sm">Cerrar sesión</button></form></div></nav><main class="container-fluid contenido"><div class="encabezado-pagina"><div><span class="sobrelinea">MI CUENTA</span><h1>Mis préstamos</h1><p>Consulta los préstamos asociados a tu usuario.</p></div></div><section class="panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Libro</th><th>Autor</th><th>Préstamo</th><th>Fecha límite</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $p): ?><tr><td><?= escapar($p['titulo']); ?></td><td><?= escapar($p['autor']); ?></td><td><?= escapar($p['fecha_prestamo']); ?></td><td><?= escapar($p['fecha_devolucion']); ?></td><td><?= escapar($p['estado_vista']); ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="text-center">No tienes préstamos registrados.</td></tr><?php endif; ?></tbody></table></div></section><?php finPagina(); ?>
